begin;
select no_plan();
set local statement_timeout='30s';
create function pg_temp.pid(n integer) returns uuid language sql immutable as $$select ('af250000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.actor(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',pg_temp.pid(n)::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.pid(n),'role','authenticated')::text,true);end$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.pid(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','teacher-planning-'||n||'@synthetic.invalid' from generate_series(1,5)n;
insert into public.profiles(id,role,name,email) select pg_temp.pid(n),case n when 1 then 'admin' when 2 then 'staff' when 3 then 'teacher' when 4 then 'assistant' else 'viewer' end,case n when 1 then '' else '합성 담당자 '||n end,'PRIVATE_ACCOUNT_CANARY'||n||'@synthetic.invalid' from generate_series(1,5)n on conflict(id) do update set role=excluded.role,name=excluded.name,email=excluded.email;
select pg_temp.actor(1);
insert into public.students(id,name,school,grade,contact,parent_contact) values(pg_temp.pid(101),'전체 공통 학생','공통 학교','중3','PRIVATE_CONTACT_CANARY','PRIVATE_PARENT_CANARY');
insert into public.classes(id,name,subject,grade,teacher,room,schedule,status,schedule_plan) values(pg_temp.pid(102),'전체 공통 수업','영어','중3','공통 교사','별관 2강','화 19:30-21:30','수강','{"memo":"PRIVATE_PLAN_CANARY","history":[{"before":"PRIVATE_HISTORY_CANARY"}],"billingPeriods":[{"id":"period1","label":"10월","startDate":"2026-10-01","endDate":"2026-10-31","totalSessions":1,"private":"PRIVATE_PERIOD_CANARY"}],"sessions":[null,{"id":"session1","date":"2026-10-27","sessionNumber":1,"billingId":"period1","startTime":"19:30","endTime":"21:30","teacherName":"공통 교사","classroomName":"별관 2강","memo":"PRIVATE_MEMO_CANARY","actualContent":"PRIVATE_LEARNING_CANARY","state":"active"}],"sessionSchedules":{"2026-10-27":{"startTime":"19:30","endTime":"21:30","teacherName":"공통 교사","memo":"PRIVATE_OVERRIDE_CANARY"}}}');
insert into public.makeup_requests(id,status,subject,approval_group,requester_id,teacher_profile_id,approver_profile_id,class_id,class_name,request_kind,reason,returned_reason,final_note,cancel_date,makeup_start_at,makeup_end_at,makeup_classroom) values(pg_temp.pid(201),'approval_pending','영어','english',pg_temp.pid(1),pg_temp.pid(1),pg_temp.pid(2),pg_temp.pid(102),'전체 공통 수업','cancel_makeup','PRIVATE_REASON_CANARY','PRIVATE_RETURN_CANARY','PRIVATE_FINAL_CANARY','2026-10-22','2026-10-24T10:00:00Z','2026-10-24T12:00:00Z','별관 2강');
create function pg_temp.makeup_filters(patch jsonb default '{}') returns jsonb language sql immutable as $$select '{"view":"approvalPending","subject":"all","teacher":"all","period":"all","dateFrom":"","dateTo":"","filterColumn":"className","search":"","sortColumn":null,"sortDirection":null}'::jsonb||patch$$;
insert into dashboard_private.continuous_class_schedule_runtime(singleton,version) values(true,1) on conflict(singleton)do update set version=1;
insert into public.classes(id,name,subject,status,schedule_storage_mode,schedule_plan) values(pg_temp.pid(103),'정규화 공통 수업','영어','수강','normalized','{}');
select set_config('app.class_schedule_mutation','release2-rpc',true);
insert into public.class_lesson_sessions(id,class_id,session_key,session_date,schedule_state,start_time,end_time,teacher_name_snapshot,classroom_name_snapshot,origin,revision,memo,teacher_note) values(pg_temp.pid(301),pg_temp.pid(103),'common-normalized','2026-10-27','active','10:00','11:30','공통 교사','별관 2강','manual',1,'PRIVATE_NORMALIZED_MEMO','PRIVATE_NORMALIZED_TEACHER_NOTE');
select set_config('app.class_schedule_mutation','',true);
-- Metadata used by the real legacy resolver is common schedule data, not notes.
update public.classes set schedule_plan=jsonb_set(jsonb_set(schedule_plan,'{sessions,1}',schedule_plan#>'{sessions,1}'||jsonb_build_object('isForced',true,'makeupRequestRole','cancel','makeupRequestId',pg_temp.pid(201))),'{sessionStates}', '{"2026-10-27":"force_active"}') where id=pg_temp.pid(102);
create temp table plan_projection_capture as select schedule_plan original, dashboard_private.teacher_common_schedule_plan_v1(schedule_plan) common from public.classes where id=pg_temp.pid(102);
grant select on plan_projection_capture to authenticated;
select pg_temp.actor(3);set local role authenticated;
select is(jsonb_array_length(public.get_dashboard_summary_sources_v1()->'students'),1,'teacher dashboard common student source is whole-read');
select ok(public.get_dashboard_summary_sources_v1()::text not like '%PRIVATE_%','teacher dashboard projection contains no contact fields');
select is((select count(*) from public.students where id=pg_temp.pid(101)),0::bigint,'teacher cannot directly read private student row');
select is((select count(*) from public.classes where id=pg_temp.pid(102)),0::bigint,'teacher cannot directly read raw class metadata');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,name}','전체 공통 수업','teacher class plan detail uses its fixed owner source');
select ok(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))::text not like '%PRIVATE_%','class plan deep projection drops notes/learning/history/unknown nested data');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,schedulePlan,sessions,1,id}','session1','deep projection preserves session identity and null hole position');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,schedulePlan,sessions,1,startTime}','19:30','deep projection preserves explicit time');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,schedulePlan,billingPeriods,0,label}','10월','deep projection preserves billing period identity and label');
select is((public.get_operations_class_schedule_numbered_page_v1('{"grade":null,"search":"","subject":null,"syncGroupId":null,"teacher":null,"termId":null}',1,15)->>'totalCount')::integer,2,'teacher class plan numbered list sees whole common class');
select lives_ok($q$select public.list_operations_catalogs_v1()$q$,'teacher common catalogs remain available after raw reference closure');
select lives_ok($q$select public.get_class_schedule_v1(pg_temp.pid(102),'2026-10-01','2026-10-31')$q$,'reader-specific normalized/legacy schedule guard allows teacher');
select ok(public.get_class_schedule_v1(pg_temp.pid(102),'2026-10-01','2026-10-31')::text not like '%PRIVATE_%','effective schedule read excludes raw private class plan content');
select is((public.list_makeup_numbered_page_v1(pg_temp.makeup_filters(),1,15)->>'totalCount')::integer,1,'teacher sees unrelated makeup common rows');
select is(public.get_makeup_detail_v1(pg_temp.pid(201))->>'className','전체 공통 수업','teacher sees unrelated makeup common detail');
select ok(public.get_makeup_detail_v1(pg_temp.pid(201))::text not like '%PRIVATE_%','makeup common detail hides reasons/snapshots/events/account fallback');
select ok(public.list_makeup_numbered_page_v1(pg_temp.makeup_filters(),1,15)::text not like '%PRIVATE_%','makeup common list uses the same projection');
select is((public.list_makeup_numbered_page_v1(pg_temp.makeup_filters('{"search":"PRIVATE_ACCOUNT_CANARY","filterColumn":"requester"}'),1,15)->>'totalCount')::integer,0,'teacher requester search cannot use account email fallback');
select throws_ok($q$select public.list_makeup_numbered_page_v1(pg_temp.makeup_filters('{"search":"PRIVATE","filterColumn":"reason"}'),1,15)$q$,'42501','operational_common_filter_forbidden','teacher cannot search hidden makeup reason');
select throws_ok($q$select public.list_makeup_numbered_page_v1(pg_temp.makeup_filters('{"sortColumn":"finalNote","sortDirection":"asc"}'),1,15)$q$,'42501','operational_common_filter_forbidden','teacher cannot sort by hidden makeup note');
select ok(public.read_operational_common_v1('options','{}')::text not like '%PRIVATE_%','teacher optional general-task references contain only common fields');
select is((select count(*) from public.makeup_requests where id=pg_temp.pid(201)),0::bigint,'raw makeup records do not reopen private details');
select lives_ok($q$select public.get_academic_curriculum_numbered_page_v2('{"periodId":null,"search":"","status":null,"subject":null,"grade":null,"teacher":null,"classroom":null,"viewMode":"all"}',1,15,true)$q$,'teacher actual curriculum v2 reader works after raw closure');
select lives_ok($q$select public.get_academic_timetable_range_v1('2026-10-20','2026-10-31',null,null,null)$q$,'teacher actual timetable reader works after raw closure');
select ok(public.get_class_schedule_v1(pg_temp.pid(103),'2026-10-01','2026-10-31')::text not like '%PRIVATE_%','normalized schedule reader excludes notes from the real session record');
select ok(public.get_class_schedule_v1(pg_temp.pid(103),'2026-10-01','2026-10-31')::text like '%common-normalized%','normalized schedule preserves stored session key');
select throws_ok($q$select public.delete_makeup_request_v2(pg_temp.pid(201),pg_temp.pid(990))$q$,'42501','makeup_request_delete_forbidden','teacher cannot read a previous manager deletion receipt');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>'{classItem,schedulePlan,sessions,1,isForced}','true'::jsonb,'forced-date binding metadata is preserved');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,schedulePlan,sessions,1,makeupRequestRole}','cancel','makeup cancel binding is preserved');
select is(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))#>>'{classItem,schedulePlan,sessionStates,2026-10-27}','force_active','legacy forced-date state string is preserved');
select diag('TEACHER_PLAN_CAPTURE='||jsonb_build_object('projection',(select to_jsonb(p) from plan_projection_capture p),'detail',public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102)),'schedule',public.get_class_schedule_v1(pg_temp.pid(102),'2026-10-01','2026-10-31'),'makeup',public.list_makeup_numbered_page_v1(pg_temp.makeup_filters(),1,15))::text);
reset role;
select pg_temp.actor(2);set local role authenticated;
select ok(public.get_operations_class_lesson_design_detail_v1(pg_temp.pid(102))::text like '%PRIVATE_PLAN_CANARY%','staff retains original class detail and editable draft');
select ok(public.get_makeup_detail_v1(pg_temp.pid(201))::text like '%PRIVATE_REASON_CANARY%','staff retains original makeup processing detail');
select is((select count(*) from public.students where id=pg_temp.pid(101)),1::bigint,'staff raw management access remains');
reset role;
select * from finish();rollback;
